const j = $input.first().json || {};
let raw = '';
if (typeof j.text === 'string') raw = j.text;
else if (j.content && Array.isArray(j.content.parts)) raw = j.content.parts.map(p => p.text || '').join('\n');
else if (Array.isArray(j.candidates) && j.candidates[0] && j.candidates[0].content && Array.isArray(j.candidates[0].content.parts)) raw = j.candidates[0].content.parts.map(p => p.text || '').join('\n');
else if (Array.isArray(j.parts)) raw = j.parts.map(p => p.text || '').join('\n');
else raw = JSON.stringify(j);
const cleaned = String(raw).trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
let obs = null; let parseError = '';
try { obs = JSON.parse(cleaned); } catch (e) {
  const m = cleaned.match(/\{[\s\S]*\}/);
  if (m) { try { obs = JSON.parse(m[0]); } catch (e2) { parseError = e2.message; } } else { parseError = e.message; }
}
if (!obs || typeof obs !== 'object' || Array.isArray(obs)) { obs = { process_name: '', raw_observations: cleaned }; }
const steps = Array.isArray(obs.steps) ? obs.steps : [];
const file = $('Normalize file info').first().json;
return [{ json: {
  file_id: file.file_id,
  file_name: file.file_name,
  observations: obs,
  observations_json: JSON.stringify(obs, null, 2),
  step_count: steps.length,
  observed_process_name: obs.process_name || '',
  parse_error: parseError,
  raw_length: String(raw).length
} }];

const first = $input.first().json || {};
const out = (first.output && typeof first.output === 'object') ? first.output : first;
const obsItem = $('Parse observations').first().json;
const file = $('Normalize file info').first().json;
const obs = obsItem.observations || {};
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const str = v => (v === undefined || v === null) ? '' : (typeof v === 'string' ? v : JSON.stringify(v));
const name = String(out.process_name || obsItem.observed_process_name || file.file_name || 'Untitled process').trim();
const date = new Date().toISOString().slice(0, 10);
const title = 'Workflow Prompt - ' + name + ' - ' + date;
const qs = Array.isArray(out.open_questions) ? out.open_questions : [];
const steps = Array.isArray(obs.steps) ? obs.steps : [];
const L = [];
L.push('WORKFLOW PROMPT: ' + name.toUpperCase());
L.push('Generated ' + new Date().toISOString() + ' from recording "' + file.file_name + '" (' + file.size_mb + ' MB). Confidence: ' + (out.confidence || 'unknown') + '.');
L.push('Source recording: ' + file.web_view_link);
L.push('');
L.push('1. SUMMARY'); L.push(str(out.summary)); L.push('');
L.push('2. N8N BUILD PROMPT (paste this to an AI workflow builder)'); L.push(str(out.n8n_build_prompt)); L.push('');
L.push('3. TOOL-AGNOSTIC AUTOMATION SPEC'); L.push(str(out.generic_spec)); L.push('');
L.push('4. OPEN QUESTIONS TO CONFIRM BEFORE BUILDING');
if (qs.length) qs.forEach((q, i) => L.push((i + 1) + '. ' + str(q))); else L.push('None identified.');
L.push('');
L.push('5. STEP-BY-STEP OBSERVATION LOG');
if (!steps.length) L.push('No structured steps were extracted from the recording.');
steps.forEach((s, i) => {
  const t = [s.start_time, s.end_time].filter(Boolean).join(' - ');
  L.push((s.index ?? (i + 1)) + '. ' + (t ? '[' + t + '] ' : '') + (s.app ? s.app + ': ' : '') + str(s.action));
  if (s.ui_element) L.push('   UI: ' + str(s.ui_element));
  if (s.data_entered) L.push('   Entered: ' + str(s.data_entered));
  if (s.data_read) L.push('   Read: ' + str(s.data_read));
  if (s.decision) L.push('   Decision: ' + str(s.decision));
  if (s.notes) L.push('   Notes: ' + str(s.notes));
});
L.push('');
L.push('6. APPS, DATA FIELDS, DECISIONS AND NARRATION');
L.push(JSON.stringify({ goal: obs.goal, actor: obs.actor, apps: obs.apps || [], data_fields: obs.data_fields || [], decisions: obs.decisions || [], inputs: obs.inputs || [], outputs: obs.outputs || [], triggers_observed: obs.triggers_observed || [], repeated_patterns: obs.repeated_patterns || [], narration_summary: obs.narration_summary, edge_cases_mentioned: obs.edge_cases_mentioned || [], uncertainties: obs.uncertainties || [] }, null, 2));
if (obs.raw_observations) { L.push(''); L.push('RAW MODEL OUTPUT (could not be parsed as JSON)'); L.push(str(obs.raw_observations)); }
return [{ json: {
  doc_title: title,
  doc_text: L.join('\n'),
  process_name: name,
  process_name_html: esc(name),
  summary: str(out.summary),
  confidence: str(out.confidence),
  open_question_count: qs.length,
  step_count: steps.length,
  file_id: file.file_id,
  file_name: file.file_name
} }];

